import { data as archiveEslintConfig } from "../inline-config/eslint";
import nodeVersions from "../registries/nodeVersions.json";
import { eslintDeps } from "./eslint.deps";

export const eslintApp: BinManager.App = {
  archives: {
    main: {
      inline: archiveEslintConfig,
    },
  },
  description: nodeVersions.eslint.description,
  files: {
    "pnpm-workspace.yaml": YAML.stringify({
      allowBuilds: {
        esbuild: false,
        "unrs-resolver": false,
      },
      // Two plugins import a package at runtime without declaring it — vanilla-extract needs
      // @typescript-eslint/utils, compat needs caniuse-lite — and pnpm's isolated layout means an
      // undeclared dependency cannot resolve at all. Patch the manifests rather than hoisting
      // everything, so the fix stays scoped to the two packages that are actually broken.
      packageExtensions: {
        "@antebudimir/eslint-plugin-vanilla-extract": {
          dependencies: { "@typescript-eslint/utils": "*" },
        },
        "eslint-plugin-compat": {
          dependencies: { "caniuse-lite": "*" },
        },
      },
      trustPolicy: {
        allowDowngrade: [
          // semver@6.3.1 (transitive dep of eslint-plugin-import) lost provenance
          // attestation compared to earlier versions — pnpm flags this as a possible
          // takeover. Package is legitimate; maintainer just didn't sign this release.
          "semver@6.3.1",
        ],
      },
    }),
  },
  links: {
    "eslint.config.mjs": "index.js",
  },
  node: {
    binPath: "node_modules/.bin/eslint",
    ...nodeVersions.eslint,
    dependencies: eslintDeps,
    lockFile:
      "br:",
  },
};
